import{DERBY_CONFIG as u,IN as l}from"./config.min.js";import{profileAt as d}from"./car.min.js";const a=1e-12,w=(t,n)=>t<n?t:n,m=(t,n)=>t>n?t:n,k=(t,n,o)=>t<n?n:t>o?o:t;export function gridX(t=u){return t.workshop.grid.map(n=>n*l)}export function isLocked(t,n=u){const o=gridX(n),s=n.workshop.slot*l;for(const e of[n.kit.frontAxle,n.kit.rearAxle]){const r=e-s,f=e+s;if(o[t]>=r&&o[t]<=f||t>0&&o[t-1]<f&&o[t]>r||t<o.length-1&&o[t]<f&&o[t+1]>r)return!0}return!1}export function limitsOf(t,n=u){const o=n.kit,s=n.workshop,e=s.minThickness*l;return isLocked(t,n)?{locked:!0,top:[s.axleWood*l,o.height],bottom:[0,0],width:[o.width,o.width]}:{locked:!1,top:[e,o.height],bottom:[0,o.height-e],width:[s.minWidth*l,o.width]}}export function clampCarve(t,n=u){const o=n.workshop.grid.length,s=n.workshop.minThickness*l,e=[],r=[];for(let i=0;i<o;i++){const c=limitsOf(i,n);e.push(k(t.bottom[i],c.bottom[0],c.bottom[1])),r.push(k(t.width[i],c.width[0],c.width[1]))}const f=[];for(let i=0;i<o;i++){const c=limitsOf(i,n);let p=e[i];i>0&&(p=m(p,e[i-1])),i<o-1&&(p=m(p,e[i+1])),f.push(k(t.top[i],m(c.top[0],p+s),c.top[1]))}return{top:f,bottom:e,width:r}}export function isCarve(t,n=u){const o=n.workshop.grid.length;if(!t||typeof t!="object")return!1;for(const s of["top","bottom","width"]){const e=t[s];if(!Array.isArray(e)||e.length!==o)return!1;for(const r of e)if(typeof r!="number"||r!==r||r===1/0||r===-1/0)return!1}return!0}export function carveFrom(t,n=u){const o=[],s=[],e=[];for(const r of gridX(n)){const[f,i,c]=d(t,r);o.push(i),s.push(f),e.push(c)}return clampCarve({top:o,bottom:s,width:e},n)}export function setPoint(t,n,o,s,e=u){const r=e.workshop.grid.length,f=e.workshop.minThickness*l,i=limitsOf(o,e);let c=k(s,i[n][0],i[n][1]);if(n==="top"){let h=t.bottom[o];o>0&&(h=m(h,t.bottom[o-1])),o<r-1&&(h=m(h,t.bottom[o+1])),c=k(c,m(i.top[0],h+f),i.top[1])}else if(n==="bottom"){let h=t.top[o];o>0&&(h=w(h,t.top[o-1])),o<r-1&&(h=w(h,t.top[o+1])),c=k(c,i.bottom[0],w(i.bottom[1],h-f))}const p={top:t.top.slice(),bottom:t.bottom.slice(),width:t.width.slice()};return p[n][o]=c,p}function b(t,n){const o=t.length,s=[];for(let r=0;r<o-1;r++)s.push((t[r+1]-t[r])/n);const e=[s[0]];for(let r=1;r<o-1;r++)e.push(s[r-1]*s[r]<=0?0:2/(1/s[r-1]+1/s[r]));return e.push(s[o-2]),e}export function curveAt(t,n,o,s){const e=t.length;if(s<=t[0])return n[0];if(s>=t[e-1])return n[e-1];let r=0;for(;r<e-2&&s>t[r+1];)r++;const f=t[r+1]-t[r],i=(s-t[r])/f,c=i*i,p=c*i;return(2*p-3*c+1)*n[r]+(p-2*c+i)*f*o[r]+(-2*p+3*c)*n[r+1]+(p-c)*f*o[r+1]}export function curvesOf(t,n=u){const o=gridX(n),s=o[1]-o[0],e=r=>{const f=b(r,s);return i=>curveAt(o,r,f,i)};return{top:e(t.top),bottom:e(t.bottom),width:e(t.width)}}export function stationsFrom(t,n=u){const o=curvesOf(t,n),s=n.workshop.sample*l,e=Math.round(n.kit.length/s),r=[];for(let f=0;f<=e;f++){const i=f===e?n.kit.length:f*s,c=o.bottom(i);r.push([i,c,m(o.top(i),c),o.width(i)])}return r}export function sameCarve(t,n){if(!t||!n)return!1;for(const o of["top","bottom","width"])for(let s=0;s<t[o].length;s++){const e=t[o][s]-n[o][s];if(e>1e-5||e<-1e-5)return!1}return!0}export function nudge(t,n,o,s=u){return t+n*(o?s.workshop.bigStep:s.workshop.step)*l}
